###############################################################################
# FLEXSEM DEB TOOLBOX
# 01B_get_simulation_catalog.R
#
# PURPOSE
# -------
# Build the catalog of available FLEXSEM simulations.
#
# A simulation is the smallest independent analysis unit used by the toolbox.
#
# The simulation catalog is used by:
#
#   • Interactive launcher
#   • Data reader
#   • Plotting
#   • Tables
#   • Animations
#
# Inputs (generated by 01_get_config_DEBV2.R)
# -------------------------------------------
# master_folder
# loaded_locations
# selected_results_folders
# selected_results_paths
#
# Output
# ------
# simulation_catalog
#
# Author : Paulo F. Lagos
# Created: 15 July 2026
###############################################################################

###############################################################################
# CHECK REQUIRED OBJECTS
###############################################################################

required_objects <- c(
  "master_folder",
  "loaded_locations",
  "selected_results_folders",
  "selected_results_paths"
)

missing_objects <- required_objects[
  !vapply(
    required_objects,
    exists,
    logical(1),
    inherits = TRUE
  )
]

if (length(missing_objects) > 0) {
  
  stop(
    paste(
      "Missing required objects:",
      paste(missing_objects, collapse = ", "),
      "\nRun 01_get_config_DEBV2.R first."
    )
  )
  
}

###############################################################################
# BUILD SIMULATION CATALOG
###############################################################################

project_name <- basename(
  dirname(master_folder)
)

simulation_catalog <- data.frame(
  
  ID = seq_along(loaded_locations),
  
  SimulationID = paste(
    project_name,
    loaded_locations,
    selected_results_folders,
    sep = "_"
  ),
  
  Project = project_name,
  
  Location = loaded_locations,
  
  ResultsFolder = selected_results_folders,
  
  Path = selected_results_paths,
  
  Status = rep(
    "Ready",
    length(loaded_locations)
  ),
  
  stringsAsFactors = FALSE
  
)

###############################################################################
# SUMMARY
###############################################################################

cat("\n")
cat("=========================================================\n")
cat(" FLEXSEM SIMULATION CATALOG\n")
cat("=========================================================\n\n")

print(
  simulation_catalog,
  row.names = FALSE
)

cat("\n")

cat(
  sprintf(
    "Available simulations : %d\n",
    nrow(simulation_catalog)
  )
)

cat("\n")
cat("=========================================================\n")